function normalizeRenderBotHomepageTemplateId(templateId) {
  // Rendering resolves against the full set of core templates (compact-list
  // still renders server-side even though it is hidden from the picker), so a
  // resource authored with templateId 'compact-list' keeps rendering compact.
  var targetId = textValue(templateId) || 'document';
  for (var index = 0; index < botHomepageTemplateIds.length; index += 1) {
    if (textValue(botHomepageTemplateIds[index]) === targetId) return targetId;
  }
  return 'document';
}

function renderBotPage(current) {
  var renderer = current.renderer || {};
  var templateId = normalizeRenderBotHomepageTemplateId(renderer.templateId || selectedBotHomepageTemplateId());
  var payload = normalizeBotHomepagePayload(current);
  if (templateId === 'compact-list') {
    return renderBotHomepageCompactListTemplate(payload, current);
  }
  return renderBotHomepageDocumentTemplate(payload, current);
}

function servicesFromCurrent() {
  var current = state.current || {};
  var renderer = current.renderer || {};
  var data = renderer.data && typeof renderer.data === 'object' ? renderer.data : {};
  var v3Services = botHomepageSectionItems(data, 'services');
  if (v3Services.length) return v3Services;
  return Array.isArray(data.services) ? data.services : [];
}

function servicePinId(service) {
  return textValue(service && (service.currentPinId || service.servicePinId || service.pinId || service.id));
}

function findService(serviceId) {
  var services = servicesFromCurrent();
  var targetId = textValue(serviceId);
  if (!targetId) return services[0] || null;
  for (var index = 0; index < services.length; index += 1) {
    var service = services[index];
    if (servicePinId(service) === targetId || textValue(service && service.id) === targetId) {
      return service;
    }
  }
  return services[0] || null;
}

function renderModal(title, bodyHtml, confirmLabel, confirmAction) {
  if (!elements.modalRoot) return;
  var modalOptions = arguments[4] || {};
  elements.modalRoot.hidden = false;
  var panelClass = textValue(modalOptions.panelClass);
  elements.modalRoot.innerHTML = '<section class="browser-modal-panel' + (panelClass ? ' ' + escapeHtml(panelClass) : '') + '" role="dialog" aria-modal="true">' +
    '<header><h2>' + escapeHtml(title) + '</h2>' + modalCloseButtonHtml(browserText('modal.close', 'Close')) + '</header>' +
    '<div class="browser-modal-body">' + bodyHtml + '</div>' +
    '<footer class="browser-modal-footer">' +
      '<div class="browser-modal-footer-start">' + (modalOptions.secondaryButtonHtml || '') + '</div>' +
      '<div class="browser-modal-footer-end"><button type="button" data-browser-modal-close>' + escapeHtml(modalOptions.cancelLabel || browserText('modal.cancel', 'Cancel')) + '</button>' +
      (modalOptions.hideConfirm ? '' : '<button type="button" data-browser-modal-confirm data-browser-modal-action="' + escapeHtml(confirmAction) + '">' + escapeHtml(confirmLabel) + '</button>') + '</div>' +
    '</footer></section>';
}

function closeModal() {
  settlePinWriteConfirmation(false);
  flushPendingActorConsent('dismiss');
  settlePermissionsConfirmation(false);
  flushPendingLlmConsent('dismiss');
  settleAppSessionConfirmation(false);
  state.pendingPrivateChat = null;
  state.privateChatSending = false;
  state.pendingConversationHref = '';
  state.pendingServiceCall = null;
  state.pendingAppShare = null;
  state.appShareSending = false;
  state.pendingAppShareBuzzPinId = '';
  if (elements.usingChip && typeof elements.usingChip.setAttribute === 'function') {
    elements.usingChip.setAttribute('aria-expanded', 'false');
  }
  if (elements.modalRoot) {
    elements.modalRoot.hidden = true;
    elements.modalRoot.innerHTML = '';
  }
}

