async function connectStandaloneWalletActor() {
  if (!isStandaloneWalletRuntime()) {
    openUsingIdentitySelector();
    return null;
  }
  rememberStandaloneWalletPlaceholder();
  if (typeof window === 'undefined' || !window.metaidwallet) {
    openWalletInstallModal();
    return null;
  }
  var wallet = window.metaidwallet;
  try {
    var connected = typeof wallet.isConnected === 'function' ? await wallet.isConnected() : null;
    var status = typeof connected === 'boolean' ? (connected ? 'connected' : 'not-connected') : textValue(connected && connected.status);
    if (status === 'locked') throw new Error(runtimeLabelValue('walletUnlockError', 'Please unlock wallet first.'));
    if (status === 'no-wallets') throw new Error(runtimeLabelValue('walletInitializeError', 'Please initialize wallet first.'));
    if (!connected || status === 'not-connected') {
      var result = typeof wallet.connect === 'function' ? await wallet.connect() : null;
      if (textValue(result && result.status) === 'canceled') {
        setStatus('wallet canceled', '');
        return null;
      }
    }

    var network = typeof wallet.getNetwork === 'function' ? await wallet.getNetwork() : null;
    var mvcAddress = typeof wallet.getAddress === 'function' ? await wallet.getAddress() : '';
    var mvcPublicKey = typeof wallet.getPublicKey === 'function' ? await wallet.getPublicKey() : '';
    var btcAddress = wallet.btc && typeof wallet.btc.getAddress === 'function' ? await wallet.btc.getAddress() : '';
    var btcPublicKey = wallet.btc && typeof wallet.btc.getPublicKey === 'function' ? await wallet.btc.getPublicKey() : '';
    var address = textValue(mvcAddress) || textValue(btcAddress);
    if (!address) throw new Error(runtimeLabelValue('walletAddressMissingError', 'Wallet extension did not return an address.'));

    var profile = await resolveWalletProfile(address);
    var label = textValue(profile.name) || shortAddress(address) || runtimeLabelValue('walletFallbackName', 'Wallet');
    var actor = {
      id: 'wallet:' + address,
      label: label,
      kind: 'wallet',
      isDefault: true,
      address: address,
      globalMetaId: textValue(profile.globalMetaId),
      avatar: textValue(profile.avatar),
      capabilities: ['template-settings'],
      wallet: {
        provider: runtimeLabelValue('walletProviderId', 'wallet-extension'),
        network: textValue(network && network.network),
        mvcAddress: textValue(mvcAddress),
        mvcPublicKey: textValue(mvcPublicKey),
        btcAddress: textValue(btcAddress),
        btcPublicKey: textValue(btcPublicKey)
      }
    };
    if (!state.runtime) state.runtime = {};
    state.runtime.actors = [actor];
    state.runtime.defaultActor = actor;
    // The connected wallet becomes the active tab's actor (per-tab). Other tabs
    // keep whatever actor they had.
    var walletTab = activeTab();
    if (walletTab) walletTab.actorId = actor.id;
    state.actorId = actor.id;
    closeStandaloneActorPanel();
    renderUsingIdentity();
    setStatus('wallet connected', '');
    return actor;
  } catch (error) {
    setStatus('error', error && error.message ? error.message : 'Wallet connection failed.');
    return null;
  }
}

function handleUsingIdentityClick(event) {
  if (event && typeof event.stopPropagation === 'function') event.stopPropagation();
  if (isStandaloneWalletRuntime()) {
    if (selectedStandaloneWalletActor()) {
      toggleStandaloneActorPanel();
      return;
    }
    openStandaloneUnsupportedModal();
    return;
  }
  openUsingIdentitySelector();
}

function openUsingIdentitySelector() {
  var actors = runtimeActors();
  if (!actors.length) {
    renderNoLocalBot();
    return;
  }
  if (!elements.modalRoot) return;
  if (elements.usingChip && typeof elements.usingChip.setAttribute === 'function') {
    elements.usingChip.setAttribute('aria-expanded', 'true');
  }
  elements.modalRoot.hidden = false;
  elements.modalRoot.innerHTML = '<section class="browser-modal-panel" role="dialog" aria-modal="true">' +
    '<header><h2>' + escapeHtml(browserText('modal.usingActorTitle', runtimeLabel('actorChip', 'Using') + ' Actor')) + '</h2><button type="button" data-browser-modal-close aria-label="' + escapeHtml(browserText('modal.close', 'Close')) + '">' + escapeHtml(browserText('modal.close', 'Close')) + '</button></header>' +
    '<div class="browser-modal-body"><div class="browser-using-options">' + actors.map(function (actor) {
      var actorData = effectiveActor(actor);
      var actorId = textValue(actorData && actorData.id);
      var name = textValue(actorData && actorData.label) || actorId || 'Actor';
      var globalMetaId = textValue(actorData && actorData.globalMetaId);
      var selected = state.actorId && actorId === state.actorId;
      return '<div class="browser-using-option"' + (selected ? ' data-browser-using-option-selected' : '') + '>' +
        '<button type="button" data-browser-actor-id="' + escapeHtml(actorId) + '"' + (selected ? ' aria-current="true"' : '') + '>' +
          '<span style="display:inline-flex;align-items:center;gap:8px;min-width:0;">' +
            avatarHtml(actorData && actorData.avatar, name, 'browser-chip-avatar') +
            '<span class="browser-chip-copy"><span class="browser-chip-title">' + escapeHtml(name) + '</span>' +
              (globalMetaId ? '<span class="browser-chip-subtitle">' + escapeHtml(globalMetaId) + '</span>' : '') +
            '</span>' +
          '</span>' +
        '</button>' +
        '<button type="button" class="browser-using-option-open browser-primary-action" data-browser-actor-open="' + escapeHtml(actorId) + '"' +
          (globalMetaId ? '' : ' disabled aria-disabled="true" title="Open homepage is unavailable without a Global MetaID"') +
          '>' + escapeHtml(browserText('actorChip.open', 'Open')) + '</button>' +
      '</div>';
    }).join('') + '</div></div></section>';
}

async function selectUsingIdentity(slug) {
  var selectedId = textValue(slug);
  var actors = runtimeActors();
  var selected = null;
  for (var index = 0; index < actors.length; index += 1) {
    if (textValue(actors[index] && actors[index].id) === selectedId) {
      selected = actors[index];
      break;
    }
  }
  if (!selected) {
    setStatus('error', runtimeLabel('actorChip', 'Actor') + ' not found.');
    return null;
  }
  // The Using Actor is owned per tab: write the selection onto the active tab's
  // actorId and mirror it onto state.actorId so endpointWithActor()/resolveUrl()
  // apply this tab's actor for resolve, trusted actions, and signing. Other tabs
  // keep their own actor. runtime.defaultActor / actors[].isDefault are the
  // host-supplied defaults and are NOT mutated here — effectiveActor() merges a
  // selected actor's missing avatar/label from the stable default when needed.
  var tab = activeTab();
  if (tab) tab.actorId = selectedId;
  state.actorId = selectedId;
  renderUsingIdentity();
  if (state.actorConsent[actorConsentKey()] === 'allow') {
    emitBridgeEvent('browser.actor.changed', { actor: sanitizedActorSnapshot(selectedActor()) });
  }
  closeModal();
  // Switching the active actor only updates the Using chip and the recorded
  // selection. It must NOT navigate or touch the address bar — the selected
  // actor is applied at action time (resolveUrl / endpointWithActor).
  return selected;
}

async function openActorHomepage(slug) {
  var selectedId = textValue(slug);
  var actors = runtimeActors();
  var actor = null;
  for (var index = 0; index < actors.length; index += 1) {
    if (textValue(actors[index] && actors[index].id) === selectedId) {
      actor = effectiveActor(actors[index]);
      break;
    }
  }
  var globalMetaId = textValue(actor && actor.globalMetaId);
  closeModal();
  if (!globalMetaId) {
    setStatus('error', runtimeLabel('actorChip', 'Actor') + ' Global MetaID is missing.');
    return Promise.resolve();
  }
  closeInspector();
  return navigateTo('metaid://' + globalMetaId);
}

function usingLabel() {
  var actor = selectedActor();
  return textValue(actor && actor.label) || textValue(state.actorId) || 'Current actor';
}

async function copyUri(action) {
  var uri = textValue(action && action.uri) ||
    textValue(state.current && state.current.normalizedUri) ||
    textValue(state.current && state.current.uri);
  if (!uri) {
    setStatus('error', 'No URI to copy.');
    return;
  }
  if (navigator && navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
    await navigator.clipboard.writeText(uri);
  }
  setStatus('copied', '');
}

function downloadReference(reference) {
  var href = resolveDownloadHref(reference);
  if (!href) {
    setStatus('error', 'Download unavailable.');
    return '';
  }
  if (typeof document !== 'undefined' && document.createElement) {
    var link = document.createElement('a');
    link.href = href;
    link.download = '';
    link.rel = 'noopener';
    link.target = '_blank';
    if (document.body && typeof document.body.appendChild === 'function') {
      document.body.appendChild(link);
      if (typeof link.click === 'function') link.click();
      if (typeof document.body.removeChild === 'function') document.body.removeChild(link);
    } else if (typeof window !== 'undefined' && typeof window.open === 'function') {
      window.open(href, '_blank', 'noopener');
    } else if (typeof window !== 'undefined' && window.location) {
      window.location.href = href;
    }
  } else if (typeof window !== 'undefined' && window.location) {
    window.location.href = href;
  }
  setStatus('download', '');
  return href;
}

function currentCreatorUri() {
  if (!state.current) return '';
  var owner = objectValue(state.current.owner);
  var proof = objectValue(state.current.proof);
  var globalMetaId = textValue(owner.globalMetaId || proof.publisherGlobalMetaId);
  return globalMetaId ? 'metaid://' + globalMetaId : '';
}

function openCreatorFromChip() {
  if (state.current && textValue(state.current.resourceType) === 'bot') {
    openInspector();
    return null;
  }
  var creatorUri = currentCreatorUri();
  if (!creatorUri) {
    openInspector();
    return null;
  }
  closeInspector();
  return navigateTo(creatorUri);
}

